'use strict';
const $=id=>document.getElementById(id);
const state={token:window.__workspaceToken || '',busy:false,people:new Map(),active:new Set(),confirm:new Set()};
delete window.__workspaceToken;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000)}
function scroll(){window.scrollTo({top:document.body.scrollHeight,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
async function api(path,body){if(!state.token){location.replace('/');throw new Error('Enter your password to open the app.')}const response=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:`Bearer ${state.token}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(60000)});let result;try{result=await response.json()}catch{throw new Error('The server did not return a readable response. Please try again.')}if(!response.ok)throw new Error(result.error||'The request could not be completed.');return result}
function message(text,user=false){const el=document.createElement('div');el.className='message '+(user?'user-message':'assistant-message');if(user)el.textContent=text;else el.innerHTML='<div class="assistant-mark" aria-hidden="true">✧</div><div class="message-content"><p>'+esc(text)+'</p></div>';$('conversation').append(el);$('welcome').hidden=true;return user?el:el.querySelector('.message-content')}
function card(c,url){const key=JSON.stringify([url,c.searchResultId]),job=c.research;const busy=state.active.has(key);let action='';if(job?.status==='done')action='<span class="saved-label">Saved ✓</span>';else if(['failed','needs_review'].includes(job?.status))action='<span class="saved-label">Needs attention</span>';else action=`<button class="enrich-button" data-enrich="${esc(key)}" ${busy?'disabled':''}>${busy?'Enriching…':['processing','submitting'].includes(job?.status)?'Check progress':'Enrich contact ↗'}</button><small>${job?'No extra credits':'Uses credits'}</small>`;
let extra='';if(state.confirm.has(key))extra=`<div class="research-note"><span>Enrich this company record? This uses Seamless credits.</span><button data-confirm="${esc(key)}">Confirm</button><button data-cancel="${esc(key)}" aria-label="Cancel enrichment">×</button></div>`;
if(job?.status==='done'){const d=job.data||{};extra='<div class="contacts">'+[['Email',d.email],['Phone',d.phone]].map(([label,value])=>`<div class="contact-field"><span>${label}</span><div class="value">${esc(value||'Not available')}</div>${value?`<button class="copy" data-copy="${esc(value)}" aria-label="Copy ${label.toLowerCase()}">Copy</button>`:''}</div>`).join('')+'</div>';}else if(job?.message)extra=`<div class="research-note error">${esc(job.message)}</div>`;else if(job?.status==='processing'||job?.status==='submitting')extra='<div class="research-note">Research in progress. You can return to this profile later.</div>';
return `<article class="company-card"><div class="company-top"><div class="company-initial">${esc((c.company||'?').slice(0,1).toUpperCase())}</div><div class="company-text"><h3>${esc(c.company||'Company not provided')}</h3><p>${esc(c.title||'Role not provided')}${c.current===true?' · Current':c.current===false?' · Previous':''}</p></div><div class="company-action">${action}</div></div>${extra}</article>`}
function renderPerson(url){const p=state.people.get(url);if(!p)return;p.container.innerHTML=`<p>${p.companies.length?`I found <strong>${esc(p.person.name)}</strong>. ${p.companies.length===1?'Here is the company record available.':'Choose the company record you want to enrich.'}`:'No company records were returned for this profile.'}</p><span class="source-tag">${p.cached?'↳ Loaded from Supabase':'✓ Search saved to Supabase'} · No credits used</span><div class="company-cards">${p.companies.map(c=>card(c,url)).join('')}</div>`;for(const older of p.older||[])older.innerHTML=p.container.innerHTML}
$('chat-form').addEventListener('submit',async e=>{e.preventDefault();if(state.busy)return;const value=$('linkedin').value.trim();let url;try{const u=new URL(value);if(u.protocol!=='https:'||!['linkedin.com','www.linkedin.com'].includes(u.hostname)||!/^\/in\/[^/]+\/?$/.test(u.pathname))throw Error();url=u.href}catch{return toast('Paste a LinkedIn person’s profile link, starting with https://www.linkedin.com/in/.')}if(!state.token){location.replace('/');return}state.busy=true;$('send').disabled=true;message(url,true);const content=message('Checking your saved profiles…');content.querySelector('p').className='loading';$('linkedin').value='';scroll();try{const result=await api('/v1/person/search',{linkedinUrl:url});const normalized=result.person.linkedinUrl;const previous=state.people.get(normalized);state.people.set(normalized,{...result,container:content,older:[...(previous?.older||[]),...(previous?[previous.container]:[])]});renderPerson(normalized)}catch(err){content.innerHTML=`<p class="error-text">${esc(err.message)}</p>`;$('linkedin').value=url}finally{state.busy=false;$('send').disabled=false;scroll();$('linkedin').focus()}});
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function enrich(key){const [url,id]=JSON.parse(key),p=state.people.get(url),c=p?.companies.find(c=>c.searchResultId===id);if(!c||state.active.has(key))return;state.confirm.delete(key);state.active.add(key);renderPerson(url);try{let result;if(c.research&&['submitting','processing'].includes(c.research.status))result=await api('/v1/person/research/status',{searchResultId:id});else result=await api('/v1/person/research',{linkedinUrl:url,searchResultId:id});c.research=result;renderPerson(url);for(let i=0;i<20&&['submitting','processing'].includes(result.status);i++){await wait(2000);result=await api('/v1/person/research/status',{searchResultId:id});c.research=result;renderPerson(url)}if(result.status==='done')toast('Contact details saved. Next time, they’ll load without enrichment.');else if(result.message)toast(result.message)}catch(err){toast(err.message);try{c.research=await api('/v1/person/research/status',{searchResultId:id})}catch{c.research={status:'needs_review',message:'Could not confirm research status. Search this profile again to load the saved state before retrying.'}}}finally{state.active.delete(key);renderPerson(url)}}
$('conversation').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.copy!==undefined){try{await navigator.clipboard.writeText(b.dataset.copy);toast('Copied')}catch{toast('Copy is unavailable in this browser. Select the contact detail to copy it.')}}if(b.dataset.enrich){const key=b.dataset.enrich,[url,id]=JSON.parse(key),c=state.people.get(url)?.companies.find(x=>x.searchResultId===id);if(['processing','submitting'].includes(c?.research?.status))return enrich(key);state.confirm.add(key);renderPerson(url)}if(b.dataset.cancel){state.confirm.delete(b.dataset.cancel);renderPerson(JSON.parse(b.dataset.cancel)[0])}if(b.dataset.confirm)enrich(b.dataset.confirm)});
function view(prospecting){$('enriching-view').hidden=prospecting;$('prospecting-view').hidden=!prospecting;$('enriching-nav').classList.toggle('active',!prospecting);$('prospecting-nav').classList.toggle('active',prospecting);$('enriching-nav').setAttribute('aria-current',prospecting?'false':'page');$('prospecting-nav').setAttribute('aria-current',prospecting?'page':'false');$('page-label').textContent=prospecting?'Prospecting':'Enriching'}
$('enriching-nav').onclick=()=>view(false);$('prospecting-nav').onclick=()=>view(true);$('back').onclick=()=>view(false);
async function checkConnection(){
 $('connect').disabled=true;
 try {
  const result=await api('/status');
  const errors=[];
  if(result.database?.status!=='READY')errors.push(result.database?.error||'Supabase is unavailable.');
  if(result.mcp?.status!=='READY')errors.push((result.keySource?`Selected server key: ${result.keySource}. `:'')+(result.mcp?.error||'Seamless is unavailable.'));
  $('connection-label').textContent=errors.length?'Connection needs attention':'Connected';
  $('connect').classList.toggle('connected',!errors.length);
  if(result.credits){$('credits').hidden=false;$('credits').textContent='View credits';$('credits-content').innerHTML=(result.credits.balances||[]).map(b=>`<p>${esc(b.label)}: <strong>${esc(b.remaining)}</strong></p>`).join('') || '<p>No unambiguous balance was found.</p>';const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Original provider response';const pre=document.createElement('pre');pre.style.cssText='white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px';pre.textContent=JSON.stringify({data:result.credits.raw,text:result.credits.text},null,2);details.append(summary,pre);$('credits-content').append(details);}
  if(errors.length){const content=message(errors.join(' '));content.querySelector('p').className='error-text';}
  else if(result.mcp.linkedinSearch===false){$('search-diagnostic').hidden=false;message('Seamless is connected. The app could not identify a LinkedIn URL search field. Click Copy search diagnostic and send it to your developer so the actual schema can be checked.');}
 }catch(err){$('connection-label').textContent='Connection needs attention';const content=message(err.message);content.querySelector('p').className='error-text';}
 finally{$('connect').disabled=false;}
}
$('connect').onclick=checkConnection;
$('credits').onclick=()=>$('credits-dialog').showModal();
$('credits-close').onclick=()=>$('credits-dialog').close();
fetch('/health',{cache:'no-store'}).then(r=>r.json()).then(build=>{$('build-label').textContent=`v${build.version} · ${build.buildId}`}).catch(()=>{$('build-label').textContent='Version unavailable'});
$('search-diagnostic').onclick=async()=>{try{const diagnostic=JSON.stringify(await api('/diagnostics/search-schema'),null,2);try{await navigator.clipboard.writeText(diagnostic);toast('Search schema copied. Paste it in our conversation.')}catch{const content=message('Copy the diagnostic below:');const pre=document.createElement('pre');pre.style.cssText='white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px';pre.textContent=diagnostic;content.append(pre)}}catch(err){toast(err.message)}};
$('logout').onclick=()=>{state.token='';location.replace('/')};
checkConnection();
